country_event = {
	id = fallen_empires_awakening.10
	title = OK
	desc = OK

	hide_window = yes

	is_triggered_only = yes

	immediate = {
		set_country_type = awakened_fallen_empire
		set_country_flag = sleepers_awake_first_sleeper
		switch = {
			trigger = has_country_flag
			fallen_empire_hive_war = {
				change_government = {
					civics = {
						civic = civic_restored_mind
						civic = civic_ancient_memories_of_war
					}
				}
			}
			fallen_empire_hive_growth = {
				change_government = {
					civics = {
						civic = civic_restored_mind
						civic = civic_ancient_memories_of_growth
						civic = civic_hive_devouring_swarm
					}
				}
			}
			fallen_empire_hive_control = {
				change_government = {
					civics = {
						civic = civic_restored_mind
						civic = civic_ancient_memories_of_control
					}
				}
				if = {
					limit = {
						is_galactic_community_formed = yes
					}
					add_to_galactic_community = yes
				}
				set_global_flag = control_awoke
				every_playable_country = {
					limit = {
						is_ai = no
					}
					country_event = { id = bio.3400 days = 1 }
				}
			}
		}
		change_country_flag = {
			icon = {
				category = "special"
				file = "hive_fe_flag_restored.dds"
			}
			background = {
				category = "backgrounds"
				file = "flag_BG_39.dds"
			}
			colors = {
				"light_orange"
				"dark_orange"
				"black"
				"null"
			}
		}
		# Capture absorbed fragments' fleet power so add_awakened_fallen_empire_fleet can offset its target;
		# integrate_country_effect transfers fleets but root.fleet_power's cache won't refresh inside this immediate block.
		set_variable = {
			which = awakening_absorbed_power
			value = 0
		}
		every_country = {
			limit = {
				has_ai_personality = fallen_empire_hive_mind
			}
			if = {
				limit = { NOT = { is_same_value = root } }
				root = {
					change_variable = {
						which = awakening_absorbed_power
						value = prev.trigger:fleet_power
					}
				}
			}
			save_event_target_as = assimilated_fe
			set_country_flag = got_assimialted
			every_playable_country = {
				limit = {
					has_communications = root
					NOT = { is_same_value = root }
				}
				country_event = { id = fallen_empires_awakening.11 }
			}
			integrate_country_effect = {
				OWNER = root
			}
		}
		random_system = {
			limit = {
				has_star_flag = last_thought_system
			}
			create_starbase = {
				size = "starbase_outpost"
				owner = root
				effect = {
					while = {
						count = 2
						create_fallen_empire_platform = yes
					}
				}
			}
		}
		event_target:fallen_empire_hive_forgotten = {
			every_owned_fleet = {
				set_owner = root
			}
		}
		add_awakened_fallen_empire_resources = yes
		add_awakened_fallen_empire_fleet = yes

		# Establish communications
		every_country = {
			limit = {
				OR = {
					is_country_type = default
					is_country_type = fallen_empire
					is_country_type = awakened_fallen_empire
				}
				NOT = { has_communications = root }
			}

			establish_communications_no_message = root
			root = { save_event_target_as = contact_empire }
			country_event = { id = action.1 }
		}
	}
}

